/* ---------- Real Google sign-in (Google Identity Services / OAuth 2.0) ---------- */

type GsiCredentialResponse = { credential?: string; select_by?: string };
type GsiIdApi = {
  initialize: (config: { client_id: string; callback: (response: GsiCredentialResponse) => void; auto_select?: boolean; cancel_on_tap_outside?: boolean }) => void;
  renderButton: (parent: HTMLElement, options: Record<string, unknown>) => void;
  disableAutoSelect: () => void;
};

function googleIdApi(): GsiIdApi | null {
  const g = (window as unknown as { google?: { accounts?: { id?: GsiIdApi } } }).google;
  return g?.accounts?.id ?? null;
}

let gisScriptPromise: Promise<boolean> | null = null;
function loadGisScript(): Promise<boolean> {
  if (typeof window === "undefined") return Promise.resolve(false);
  if (googleIdApi()) return Promise.resolve(true);
  if (!gisScriptPromise) {
    gisScriptPromise = new Promise<boolean>((resolve) => {
      const script = document.createElement("script");
      script.src = "https://accounts.google.com/gsi/client";
      script.async = true;
      script.defer = true;
      script.onload = () => resolve(!!googleIdApi());
      script.onerror = () => resolve(false);
      document.head.appendChild(script);
    });
  }
  return gisScriptPromise;
}

function GoogleSetupSteps() {
  const origin = typeof window !== "undefined" ? window.location.origin : "";
  return (
    <ol className="list-decimal space-y-1.5 pl-5 text-sm text-[var(--dim)]">
      <li>Follow Google's <a href="https://developers.google.com/identity/gsi/web/guides/display-button" target="_blank" rel="noreferrer" className="font-semibold text-[var(--accent)] underline underline-offset-2">Sign in with Google setup guide</a> and create (or open) a project in Google Cloud Console.</li>
      <li>Under <span className="font-medium text-[var(--text)]">APIs &amp; Services → OAuth consent screen</span>, configure the consent screen for your organization.</li>
      <li>Under <span className="font-medium text-[var(--text)]">APIs &amp; Services → Credentials</span>, create an <span className="font-medium text-[var(--text)]">OAuth client ID</span> of type <span className="font-medium text-[var(--text)]">Web application</span>.</li>
      <li>Add this app's address as an <span className="font-medium text-[var(--text)]">Authorized JavaScript origin</span>: <span className="mt-0.5 block font-mono text-xs break-all text-[var(--text)]">{origin}</span></li>
      <li>Paste the client ID (it ends in <span className="font-mono text-xs">.apps.googleusercontent.com</span>) into the app — an administrator can do it under <span className="font-medium text-[var(--text)]">Admin Review → Google sign-in connection</span>.</li>
    </ol>
  );
}

function GoogleSignInPanel({ clientId, onSignIn }: { clientId: string | null; onSignIn: (u: GoogleUser) => void }) {
  const buttonHostRef = useRef<HTMLDivElement | null>(null);
  const onSignInRef = useRef(onSignIn);
  onSignInRef.current = onSignIn;
  const [status, setStatus] = useState<"idle" | "loading" | "ready" | "verifying" | "error">("idle");
  const [error, setError] = useState<string | null>(null);
  const verify = useMutation({
    mutationFn: (credential: string) => api.verifyGoogleCredential({ credential }),
    onSuccess: (u) => { setStatus("idle"); onSignInRef.current(u); },
    onError: (e) => { setStatus("error"); setError(e instanceof Error ? e.message : "Google sign-in could not be verified. Please try again."); },
  });
  const verifyRef = useRef(verify);
  verifyRef.current = verify;

  useEffect(() => {
    if (!clientId) return;
    let cancelled = false;
    setStatus("loading"); setError(null);
    void loadGisScript().then((loaded) => {
      if (cancelled) return;
      const idApi = loaded ? googleIdApi() : null;
      const host = buttonHostRef.current;
      if (!idApi || !host) { setStatus("error"); setError("Couldn't load Google's sign-in library. Check your connection, allow scripts from accounts.google.com, and try again."); return; }
      try {
        idApi.initialize({ client_id: clientId, auto_select: false, cancel_on_tap_outside: true, callback: (response) => { if (response.credential) { setStatus("verifying"); setError(null); verifyRef.current.mutate(response.credential); } } });
        host.replaceChildren();
        idApi.renderButton(host, { type: "standard", theme: "outline", size: "large", text: "signin_with", shape: "rectangular", logo_alignment: "left", width: 320 });
        setStatus("ready");
      } catch { setStatus("error"); setError("Google's sign-in button couldn't be started. Please reload and try again."); }
    });
    return () => { cancelled = true; };
  }, [clientId]);

  if (!clientId) {
    return (
      <div className="rounded-[var(--radius)] border border-amber-300 bg-amber-50 px-3 py-3">
        <p className="text-sm font-semibold text-amber-950">Google sign-in isn't connected yet</p>
        <p className="mt-1 text-sm text-amber-900">Use the demo accounts below.</p>
      </div>
    );
  }
  return (
    <div className="space-y-2">
      <div ref={buttonHostRef} className="flex min-h-[44px] items-center justify-center" aria-label="Sign in with Google" />
      {status === "loading" && <p className="text-center text-sm text-[var(--dim)]">Loading Google sign-in…</p>}
      {status === "verifying" && <p className="text-center text-sm text-[var(--dim)]">Verifying your Google sign-in…</p>}
      {error && <p role="alert" className="rounded-[var(--radius)] border border-red-300 bg-red-50 px-3 py-2 text-sm text-red-900">{error}</p>}
    </div>
  );
}

function loadStoredUser(): GoogleUser | null {
  try {
    const raw = window.localStorage.getItem("cbi-google-user");
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<GoogleUser>;
    if (parsed.googleId && parsed.email && parsed.name) return { googleId: parsed.googleId, email: parsed.email, name: parsed.name, provider: parsed.provider, sessionToken: parsed.sessionToken, sessionFreshUntil: parsed.sessionFreshUntil, sessionMethod: parsed.sessionMethod };
    return null;
  } catch { return null; }
}

function formatDate(iso: string): string {
  const d = new Date(`${iso}T00:00:00`);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" });
}
function formatShortDate(iso: string): string {
  const d = new Date(`${iso}T00:00:00`);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}
function downloadTextFile(filename: string, text: string, mime: string): void {
  const blob = new Blob([text], { type: `${mime};charset=utf-8` });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 5000);
}

/* ---------- Real QR codes ---------- */
function QrPattern({ code, size = 200 }: { code: string; size?: number }) {
  const [url, setUrl] = useState<string | null>(null);
  useEffect(() => {
    let cancelled = false;
    QRCode.toDataURL(code, { width: size * 2, margin: 2, errorCorrectionLevel: "M" })
      .then((u) => { if (!cancelled) setUrl(u); })
      .catch(() => { if (!cancelled) setUrl(null); });
    return () => { cancelled = true; };
  }, [code, size]);
  if (!url) return (<div style={{ width: size, height: size }} className="flex items-center justify-center bg-white px-3 text-center text-sm text-[#5b6b7a]">Preparing QR pass…</div>);
  return (<img src={url} width={size} height={size} alt={`QR code pass for code ${code} — scan it at the door`} className="max-w-full bg-white" />);
}
async function qrPngDataUrl(code: string): Promise<string | null> {
  try { return await QRCode.toDataURL(code, { width: 500, margin: 2, errorCorrectionLevel: "M" }); } catch { return null; }
}
function icsEscape(text: string): string { return text.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r\n|\r|\n/g, "\\n"); }
function icsFold(line: string): string { if (line.length <= 75) return line; const parts: string[] = [line.slice(0, 75)]; let rest = line.slice(75); while (rest.length > 0) { parts.push(` ${rest.slice(0, 74)}`); rest = rest.slice(74); } return parts.join("\r\n"); }
function icsStamp(d: Date): string { const p = (n: number) => String(n).padStart(2, "0"); return `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}T${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}Z`; }
function parseTimeRange(timeText: string): { start: [number, number]; end: [number, number] | null } | null {
  const matches = [...timeText.matchAll(/(\d{1,2}):(\d{2})\s*(AM|PM)/gi)];
  const toHM = (m: RegExpMatchArray): [number, number] => { let h = Number(m[1] ?? "0") % 12; if ((m[3] ?? "").toUpperCase() === "PM") h += 12; return [h, Number(m[2] ?? "0")]; };
  const first = matches[0]; if (!first) return null; const second = matches[1]; return { start: toHM(first), end: second ? toHM(second) : null };
}
async function buildCalendarInvite(reg: Registration, attachLinks: Array<{ name: string; url: string }> = []): Promise<Blob> {
  const orgName = reg.orgName || "Organization";
  const code = reg.code ?? ""; const day = reg.eventDate.replace(/-/g, ""); const p2 = (n: number) => String(n).padStart(2, "0");
  const lines: string[] = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Event Registration & Check-In//EN", "CALSCALE:GREGORIAN", "METHOD:PUBLISH", "BEGIN:VEVENT", `UID:${code || `reg-${reg.id}`}@event-registration`, `DTSTAMP:${icsStamp(new Date())}`];
  const range = parseTimeRange(reg.eventTimeText);
  if (range) { const [sh, sm] = range.start; lines.push(`DTSTART:${day}T${p2(sh)}${p2(sm)}00`); let endH = sh + 2; let endM = sm; if (range.end) { [endH, endM] = range.end; } lines.push(`DTEND:${day}T${p2(endH % 24)}${p2(endM)}00`); }
  else { const start = new Date(`${reg.eventDate}T00:00:00`); const end = new Date(start.getTime() + 24 * 60 * 60 * 1000); const ymd = (d: Date) => `${d.getFullYear()}${p2(d.getMonth() + 1)}${p2(d.getDate())}`; lines.push(`DTSTART;VALUE=DATE:${ymd(start)}`); lines.push(`DTEND;VALUE=DATE:${ymd(end)}`); }
  lines.push(`SUMMARY:${icsEscape(`${reg.eventTitle} — ${orgName}`)}`); lines.push(`LOCATION:${icsEscape(reg.eventLocation)}`);
  const description = [`You are confirmed to attend ${reg.eventTitle} at ${orgName}.`, "", `Your admission pass code is ${code}.`, "Your QR pass is attached to this calendar invite as an image (qr-pass). The QR code is optional — this text code on its own is enough: the greeter can type it in at the door to verify your approval and check you in.", "", `Registered to: ${reg.name}`, `Event time: ${reg.eventTimeText}`, ...(reg.attachments.length > 0 ? ["", `Event files for confirmed guests: ${reg.attachments.map((a) => a.name).join(", ")} — attached to this invite as links${attachLinks.length > 0 ? "" : " and available any time in My Events in the app"}.`] : [])].join("\n");
  lines.push(`DESCRIPTION:${icsEscape(description)}`);
  if (code) { const png = await qrPngDataUrl(code); const base64 = png?.split(",")[1]; if (base64) lines.push(`ATTACH;FMTTYPE=image/png;ENCODING=BASE64;VALUE=BINARY;X-FILENAME=qr-pass-${code}.png:${base64}`); }
  for (const a of attachLinks) lines.push(`ATTACH;VALUE=URI:${a.url}`);
  lines.push("END:VEVENT", "END:VCALENDAR");
  return new Blob([`${lines.map(icsFold).join("\r\n")}\r\n`], { type: "text/calendar;charset=utf-8" });
}
async function downloadCalendarInvite(reg: Registration): Promise<void> { let attachLinks: Array<{ name: string; url: string }> = []; if (reg.attachments.length > 0) { try { const got = await Promise.all(reg.attachments.map((a) => api.getAttachmentUrl({ attachmentId: a.id, registrationId: reg.id, email: reg.email }))); attachLinks = got.map((g) => ({ name: g.name, url: g.url })); } catch { attachLinks = []; } } const blob = await buildCalendarInvite(reg, attachLinks); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `invite-${reg.code ?? reg.id}.ics`; document.body.appendChild(a); a.click(); a.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 5000); }
function CalendarInviteButton({ reg }: { reg: Registration }) {
  const branding = useBranding();
  const [busy, setBusy] = useState(false); const [note, setNote] = useState<string | null>(null);
  if (!reg.code) return null;
  const primary = branding?.primaryColor ?? "#0b3d6e";
  return (<div className="w-full"><button type="button" disabled={busy} onClick={() => { setBusy(true); setNote(null); downloadCalendarInvite(reg).then(() => setNote("Invite downloaded — open the .ics file to add it. The calendar entry includes your pass code and QR pass.")).catch(() => setNote("Couldn't create the invite file. Your pass code above still works at the door.")).finally(() => setBusy(false)); }} className="w-full rounded-[var(--radius)] border-2 px-4 py-2.5 font-semibold disabled:opacity-50" style={{ borderColor: primary, color: primary }}>{busy ? "Preparing invite…" : "📅 Add to calendar (.ics)"}</button>{note && <p className="mt-1.5 text-center text-xs text-[var(--dim)]">{note}</p>}</div>);
}
function StatusBadge({ status }: { status: Registration["status"] }) {
  const branding = useBranding();
  const primary = branding?.primaryColor ?? "#0b3d6e";
  const styles: Record<Registration["status"], string> = { pending: "bg-amber-100 text-amber-900 border-amber-300", approved: "bg-emerald-100 text-emerald-900 border-emerald-300", denied: "bg-red-100 text-red-900 border-red-300", checked_in: "text-white", revoked: "bg-stone-800 text-white border-stone-800", waitlisted: "bg-sky-100 text-sky-900 border-sky-300", cancelled: "bg-stone-200 text-stone-800 border-stone-400" };
  const labels: Record<Registration["status"], string> = { pending: "Tentative", approved: "Confirmed", denied: "Not approved", checked_in: "Checked in", revoked: "Cancelled", waitlisted: "Waitlisted", cancelled: "Cancelled by you" };
  return (<span className={`inline-block rounded-full border px-2.5 py-0.5 text-xs font-semibold ${styles[status]}`} style={status === "checked_in" ? { backgroundColor: primary, borderColor: primary } : undefined}>{labels[status]}</span>);
}
export function statusLabel(status: string): string {
  switch (status) {
    case "pending": return "Tentative — awaiting approval";
    case "approved": return "Confirmed";
    case "checked_in": return "Checked in";
    case "denied": return "Not approved";
    case "waitlisted": return "Waitlisted";
    case "cancelled": return "Cancelled by attendee";
    case "revoked": return "Cancelled";
    default: return status;
  }
}
const REMINDER_OPTIONS: Array<{ id: "1d" | "3h" | "1h"; label: string }> = [
  { id: "1d", label: "1 day before" },
  { id: "3h", label: "3 hours before" },
  { id: "1h", label: "1 hour before" },
];
export function reminderSummary(reg: Registration): string {
  const picks = reg.reminderChoices.length > 0 ? reg.reminderChoices.map((c) => REMINDER_OPTIONS.find((o) => o.id === c)?.label ?? c).join(" · ") : "Day before (default)";
  const channel = reg.notifyChannel === "text" ? "by text" : reg.notifyChannel === "both" ? "by email & text" : "by email";
  return `${picks} — ${channel}`;
}
function ReminderChoicesEditor({ reg }: { reg: Registration }) {
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const [choices, setChoices] = useState<Array<"1d" | "3h" | "1h">>(reg.reminderChoices);
  const [note, setNote] = useState<string | null>(null);
  useEffect(() => { setChoices(reg.reminderChoices); }, [reg.reminderChoices]);
  const save = useMutation({
    mutationFn: () => api.updateReminderChoices({ registrationId: reg.id, email: reg.email, choices }),
    onSuccess: () => { setNote("Reminder choices saved."); queryClient.invalidateQueries({ queryKey: ["myRegistrations"] }); queryClient.invalidateQueries({ queryKey: ["registrations"] }); },
    onError: (e) => setNote(e instanceof Error ? e.message : "Couldn't save reminder choices."),
  });
  const toggle = (id: "1d" | "3h" | "1h") => setChoices((prev) => (prev.includes(id) ? prev.filter((c) => c !== id) : [...prev, id]));
  const dirty = JSON.stringify([...choices].sort()) !== JSON.stringify([...reg.reminderChoices].sort());
  return (
    <div className="rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-4 py-3">
      <button type="button" onClick={() => setOpen((v) => !v)} aria-expanded={open} className="flex w-full items-center justify-between gap-2 text-left">
        <span className="text-sm font-semibold text-[var(--text)]">🔔 Reminders — <span className="font-normal text-[var(--dim)]">{reminderSummary(reg)}</span></span>
        <span aria-hidden className="text-[var(--dim)]">{open ? "▾" : "▸"}</span>
      </button>
      {open && (
        <div className="mt-2.5">
          <div className="flex flex-wrap gap-2">
            {REMINDER_OPTIONS.map((o) => (
              <label key={o.id} className="flex cursor-pointer items-center gap-2 rounded-full border border-[var(--border)] bg-[var(--bg)] px-3 py-1.5 text-sm font-medium text-[var(--text)]">
                <input type="checkbox" checked={choices.includes(o.id)} onChange={() => toggle(o.id)} className="h-4 w-4" aria-label={`Reminder ${o.label} for ${reg.eventTitle}`} /> {o.label}
              </label>
            ))}
          </div>
          <p className="mt-1.5 text-xs text-[var(--dim)]">None checked = day before (default).</p>
          {dirty && <button type="button" disabled={save.isPending} onClick={() => { setNote(null); save.mutate(); }} className="mt-2 rounded-[var(--radius)] bg-[var(--accent)] px-3.5 py-2 text-sm font-semibold text-white disabled:opacity-50">{save.isPending ? "Saving…" : "Save reminder choices"}</button>}
          {note && <p role="status" className="mt-1.5 text-sm text-[var(--dim)]">{note}</p>}
        </div>
      )}
    </div>
  );
}
function WaitlistOfferCard({ reg }: { reg: Registration }) {
  const queryClient = useQueryClient();
  const [note, setNote] = useState<string | null>(null);
  const respond = useMutation({
    mutationFn: (decision: "accept" | "decline") => api.respondToWaitlistOffer({ registrationId: reg.id, email: reg.email, decision }),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["myRegistrations"] }); queryClient.invalidateQueries({ queryKey: ["registrations"] }); queryClient.invalidateQueries({ queryKey: ["events"] });
      setNote(data.outcome === "accepted" ? "You've accepted the spot — it's held for you while the approvers confirm. Your QR pass is issued at confirmation and will appear here." : data.outcome === "declined" ? "You've given up the spot — it goes to the next person on the waitlist." : data.outcome === "expired" ? "That offer had already expired — the spot went to the next person. You're still on the waitlist for any future opening." : "That offer is no longer active.");
    },
    onError: (e) => setNote(e instanceof Error ? e.message : "Couldn't record your answer."),
  });
  if (reg.status !== "waitlisted" || !reg.waitlistOfferedAt) return null;
  return (
    <div className="rounded-[var(--radius)] border-2 border-emerald-500 bg-emerald-50 px-4 py-3">
      <p className="font-display font-semibold text-emerald-950">🎉 A spot opened up for {reg.eventTitle}!</p>
      <p className="mt-1 text-sm text-emerald-900">You're next on the waitlist, and the spot is being held for you{reg.waitlistExpiresAt ? <> until <strong>{new Date(reg.waitlistExpiresAt).toLocaleString()}</strong></> : ""}. Accept it and the spot stays yours while the approvers confirm — your QR pass is issued at confirmation. If the hold lapses or you decline, the spot goes to the next person.</p>
      <div className="mt-2 flex flex-wrap gap-2">
        <button type="button" disabled={respond.isPending} onClick={() => respond.mutate("accept")} className="rounded-[var(--radius)] bg-emerald-700 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">Accept the spot</button>
        <button type="button" disabled={respond.isPending} onClick={() => respond.mutate("decline")} className="rounded-[var(--radius)] border border-emerald-700 px-4 py-2.5 text-sm font-semibold text-emerald-900 disabled:opacity-50">No thanks — release it</button>
      </div>
      {note && <p role="status" className="mt-2 text-sm text-emerald-950">{note}</p>}
    </div>
  );
}
/* Add-to-wallet: one tap per wallet builds the complete platform pass
   payload from the server (event details + QR code in the org's colors).
   Delivery activates when the organization connects its wallet account;
   until then the payload can be downloaded exactly as it will be issued. */
function WalletButtons({ reg }: { reg: Registration }) {
  const [info, setInfo] = useState<{ platform: string; payload: string; note: string } | null>(null);
  const flagsOn = useFeatureEnabled(reg.orgId, "wallet_passes");
  const [error, setError] = useState<string | null>(null);
  const get = useMutation({
    mutationFn: (platform: "apple" | "google" | "samsung") => api.getWalletPass({ registrationId: reg.id, email: reg.email, googleId: reg.googleId ?? undefined, platform }),
    onSuccess: (d) => { setError(null); setInfo(d); },
    onError: (e) => setError(e instanceof Error ? e.message : "Couldn't prepare the wallet pass."),
  });
  const btnCls = "rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm font-semibold text-[var(--text)] disabled:opacity-50";
  const platformName = info?.platform === "apple" ? "Apple Wallet" : info?.platform === "google" ? "Google Wallet" : "Samsung Pay";
  if (!flagsOn) return null;
  return (
    <div className="w-full">
      <p className="text-center text-xs font-semibold tracking-wide text-[var(--dim)] uppercase">Add to wallet</p>
      <div className="mt-1.5 flex flex-wrap justify-center gap-2">
        <button type="button" disabled={get.isPending} onClick={() => get.mutate("apple")} className={btnCls}>Apple Wallet</button>
        <button type="button" disabled={get.isPending} onClick={() => get.mutate("google")} className={btnCls}>Google Wallet</button>
        <button type="button" disabled={get.isPending} onClick={() => get.mutate("samsung")} className={btnCls}>Samsung Pay</button>
      </div>
      {error && <p role="alert" className="mt-2 text-center text-sm text-[var(--bad)]">{error}</p>}
      {info && (
        <div className="mt-3 rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] px-3 py-3 text-left">
          <p className="text-sm font-semibold text-[var(--text)]">{platformName} pass — {reg.eventTitle}</p>
          <p className="mt-1 text-sm text-[var(--dim)]">{info.note}</p>
          <div className="mt-2 flex flex-wrap gap-2">
            <button type="button" onClick={() => downloadTextFile(`${reg.eventTitle.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}-wallet-pass.json`, info.payload, "application/json")} className={btnCls}>⬇ Download pass data</button>
            <button type="button" onClick={() => setInfo(null)} className={btnCls}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

/* Attendee → event team messaging, on the attendee's own registration:
   collapsed by default; the thread, a send box, and the reply
   notification emails (each with its live reply-by-email link). */
function AttendeeMessageThread({ reg }: { reg: Registration }) {
  const queryClient = useQueryClient();
  const flagsOn = useFeatureEnabled(reg.orgId, "attendee_messaging");
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState("");
  const [note, setNote] = useState<string | null>(null);
  const threadQ = useQuery({ queryKey: ["myEventMessages", reg.id], queryFn: () => api.listMyEventMessages({ registrationId: reg.id, email: reg.email, googleId: reg.googleId ?? undefined }), enabled: open });
  const send = useMutation({
    mutationFn: () => api.sendEventMessage({ registrationId: reg.id, email: reg.email, googleId: reg.googleId ?? undefined, body: draft.trim() }),
    onSuccess: () => { setDraft(""); setNote("Message sent — the event team can reply here or from their email."); void queryClient.invalidateQueries({ queryKey: ["myEventMessages", reg.id] }); },
    onError: (e) => setNote(e instanceof Error ? e.message : "Couldn't send the message."),
  });
  const messages = threadQ.data?.messages ?? [];
  const notifications = threadQ.data?.notifications ?? [];
  if (!flagsOn) return null;
  return (
    <div className="rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-4 py-3">
      <button type="button" onClick={() => setOpen((v) => !v)} aria-expanded={open} className="flex w-full items-center justify-between gap-2 text-left">
        <span className="text-sm font-semibold text-[var(--text)]">💬 Message the event team</span>
        <span aria-hidden className="text-[var(--dim)]">{open ? "▾" : "▸"}</span>
      </button>
      {open && (
        <div className="mt-2.5 space-y-3">
          {threadQ.isPending && <p className="text-sm text-[var(--dim)]">Loading…</p>}
          {threadQ.isError && <p role="alert" className="text-sm text-[var(--bad)]">Messages couldn't be loaded.</p>}
          {messages.length === 0 && !threadQ.isPending && <p className="text-sm text-[var(--dim)]">Ask a question or request a change — the event's admins and registrars will see it.</p>}
          {messages.map((m) => (
            <div key={m.id} className={`rounded-[var(--radius)] px-3 py-2 text-sm ${m.fromAttendee ? "bg-[var(--surface-alt)]" : "border border-[var(--border)] bg-[var(--bg)]"}`}>
              <p className="text-xs font-semibold text-[var(--dim)]">{m.fromAttendee ? "You" : `${m.senderName} · Event team`} · {new Date(m.createdAt).toLocaleString()}</p>
              <p className="mt-0.5 whitespace-pre-line text-[var(--text)]">{m.body}</p>
            </div>
          ))}
          <div>
            <label htmlFor={`msg-${reg.id}`} className="sr-only">Message the event team about {reg.eventTitle}</label>
            <textarea id={`msg-${reg.id}`} value={draft} onChange={(e) => setDraft(e.target.value)} rows={3} maxLength={2000} placeholder="Write your message…" className="w-full rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-3 py-2.5 text-[var(--text)]" />
            <button type="button" disabled={send.isPending || !draft.trim()} onClick={() => send.mutate()} className="mt-2 rounded-[var(--radius)] bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{send.isPending ? "Sending…" : "Send message"}</button>
            {note && <p role="status" className="mt-1.5 text-sm text-[var(--dim)]">{note}</p>}
          </div>
          {notifications.map((n) => (
            <div key={n.token} className="rounded-[var(--radius)] border border-dashed border-[var(--border)] px-3 py-2.5 text-sm">
              <p className="font-semibold text-[var(--text)]">✉ Reply notification email — preview</p>
              <p className="mt-0.5 text-[var(--dim)]"><span className="font-semibold text-[var(--text)]">{n.senderName} (event team):</span> {n.body}</p>
              {n.usedAt ? (<p className="mt-1 text-xs text-[var(--dim)]">You replied from this email ✓</p>) : new Date(n.expiresAt).getTime() < Date.now() ? (<p className="mt-1 text-xs text-[var(--dim)]">The reply link in this email has expired — reply here instead.</p>) : (<a href={`${appBaseUrl()}?msgreply=${n.token}`} className="mt-1.5 inline-block rounded-[var(--radius)] border border-[var(--border)] px-3 py-1.5 text-sm font-semibold text-[var(--text)]">Reply from this email</a>)}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* Staff side of event messaging (admins + registrars): the inbox of
   attendee threads, with in-app replies and the notification emails
   (each with its live reply-by-email link). */
function EventMessageInbox({ org, googleUser }: { org: Org; googleUser: GoogleUser }) {
  const queryClient = useQueryClient();
  const requester = { orgId: org.id, requestedByGoogleId: googleUser.googleId, requestedByEmail: googleUser.email, sessionToken: googleUser.sessionToken };
  const [selectedReg, setSelectedReg] = useState<number | null>(null);
  const [reply, setReply] = useState("");
  const [note, setNote] = useState<string | null>(null);
  const threadsQ = useQuery({ queryKey: ["eventMessageThreads", org.id], queryFn: () => api.listEventMessageThreads(requester) });
  const threadQ = useQuery({ queryKey: ["eventMessageThread", org.id, selectedReg], queryFn: () => api.getEventMessageThread({ ...requester, registrationId: selectedReg ?? 0 }), enabled: selectedReg !== null });
  const replyMut = useMutation({
    mutationFn: () => api.replyToEventMessage({ ...requester, registrationId: selectedReg ?? 0, body: reply.trim() }),
    onSuccess: () => { setReply(""); setNote("Reply sent — the attendee can answer here or from their notification email."); void queryClient.invalidateQueries({ queryKey: ["eventMessageThread", org.id, selectedReg] }); void queryClient.invalidateQueries({ queryKey: ["eventMessageThreads", org.id] }); },
    onError: (e) => setNote(e instanceof Error ? e.message : "Couldn't send the reply."),
  });
  const threads = threadsQ.data?.threads ?? [];
  const myNotifications = (threadQ.data?.notifications ?? []).filter((n) => n.recipientEmail.toLowerCase() === googleUser.email.toLowerCase());
  return (
    <div className="rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-4 py-4">
      <h3 className="font-display text-lg font-semibold text-[var(--text)]">💬 Attendee messages</h3>
      <p className="mt-0.5 text-sm text-[var(--dim)]">Questions and requests from attendees, one conversation per registration. Reply here, or from the notification email.</p>
      {threadsQ.isPending && <p className="mt-2 text-sm text-[var(--dim)]">Loading…</p>}
      {threadsQ.isError && <p role="alert" className="mt-2 text-sm text-[var(--bad)]">Messages couldn't be loaded.</p>}
      {threads.length === 0 && !threadsQ.isPending && <p className="mt-2 text-sm text-[var(--dim)]">No attendee messages yet.</p>}
      <div className="mt-3 space-y-2">
        {threads.map((t) => (
          <button key={t.registrationId} type="button" onClick={() => { setSelectedReg(t.registrationId); setNote(null); }} aria-pressed={selectedReg === t.registrationId} className={`w-full rounded-[var(--radius)] border-2 px-3 py-2.5 text-left ${selectedReg === t.registrationId ? "bg-[var(--surface-alt)]" : "border-[var(--border)]"}`} style={selectedReg === t.registrationId ? { borderColor: org.primaryColor } : undefined}>
            <span className="flex items-center justify-between gap-2"><span className="text-sm font-semibold text-[var(--text)]">{t.attendeeName} — {t.eventTitle}</span>{t.unreadCount > 0 && <span className="rounded-full bg-[var(--accent)] px-2 py-0.5 text-xs font-bold text-white">{t.unreadCount} new</span>}</span>
            <span className="mt-0.5 block truncate text-sm text-[var(--dim)]">{t.lastFromAttendee ? "" : "You: "}{t.lastBody}</span>
          </button>
        ))}
      </div>
      {selectedReg !== null && (
        <div className="mt-3 space-y-3 border-t border-[var(--border)] pt-3">
          {threadQ.isPending && <p className="text-sm text-[var(--dim)]">Loading conversation…</p>}
          {(threadQ.data?.messages ?? []).map((m) => (
            <div key={m.id} className={`rounded-[var(--radius)] px-3 py-2 text-sm ${m.fromAttendee ? "border border-[var(--border)] bg-[var(--bg)]" : "bg-[var(--surface-alt)]"}`}>
              <p className="text-xs font-semibold text-[var(--dim)]">{m.fromAttendee ? `${m.senderName} · Attendee` : `${m.senderName} · Event team`} · {new Date(m.createdAt).toLocaleString()}</p>
              <p className="mt-0.5 whitespace-pre-line text-[var(--text)]">{m.body}</p>
            </div>
          ))}
          {myNotifications.map((n) => (
            <div key={n.token} className="rounded-[var(--radius)] border border-dashed border-[var(--border)] px-3 py-2.5 text-sm">
              <p className="font-semibold text-[var(--text)]">✉ Notification email to you — preview</p>
              <p className="mt-0.5 text-[var(--dim)]">{n.body}</p>
              {n.usedAt ? (<p className="mt-1 text-xs text-[var(--dim)]">You replied from this email ✓</p>) : new Date(n.expiresAt).getTime() < Date.now() ? (<p className="mt-1 text-xs text-[var(--dim)]">The reply link in this email has expired — reply here instead.</p>) : (<a href={`${appBaseUrl()}?msgreply=${n.token}`} className="mt-1.5 inline-block rounded-[var(--radius)] border border-[var(--border)] px-3 py-1.5 text-sm font-semibold text-[var(--text)]">Reply from this email</a>)}
            </div>
          ))}
          <div>
            <label htmlFor="inbox-reply" className="sr-only">Reply to the attendee</label>
            <textarea id="inbox-reply" value={reply} onChange={(e) => setReply(e.target.value)} rows={3} maxLength={2000} placeholder="Write a reply…" className="w-full rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-3 py-2.5 text-[var(--text)]" />
            <button type="button" disabled={replyMut.isPending || !reply.trim()} onClick={() => replyMut.mutate()} className="mt-2 rounded-[var(--radius)] bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{replyMut.isPending ? "Sending…" : "Send reply"}</button>
            {note && <p role="status" className="mt-1.5 text-sm text-[var(--dim)]">{note}</p>}
          </div>
        </div>
      )}
    </div>
  );
}

/* The reply-by-email landing: opened from a notification email's Reply
   link (?msgreply=<token>). The token alone is the credential and is
   scoped to one thread — the page only ever shows that conversation's
   event and the one message being answered. */
function MessageReplyLanding({ token, onDismiss }: { token: string; onDismiss: () => void }) {
  const [body, setBody] = useState("");
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const infoQ = useQuery({ queryKey: ["eventMessageReplyInfo", token], queryFn: () => api.getEventMessageReplyInfo({ token }) });
  const send = useMutation({ mutationFn: () => api.replyByEventMessageToken({ token, body: body.trim() }), onSuccess: () => setSent(true), onError: (e) => setError(e instanceof Error ? e.message : "Couldn't send the reply.") });
  const info = infoQ.data;
  const dismissCls = "mt-3 rounded-[var(--radius)] border border-[var(--border)] px-4 py-2.5 text-sm font-semibold text-[var(--text)]";
  return (
    <section aria-label="Reply by email" className="mx-auto mb-5 max-w-xl rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-5 py-5">
      <p className="text-sm font-semibold text-[var(--text)]">Reply by email</p>
      {infoQ.isPending && <p className="mt-2 text-sm text-[var(--dim)]">Checking your reply link…</p>}
      {info && info.outcome !== "ok" && (<>
        <p className="mt-2 text-sm text-[var(--text)]">{info.outcome === "used" ? "This reply link has already been used — each notification email carries a one-time link. You can reply from the app instead." : info.outcome === "expired" ? "This reply link has expired (reply links last 7 days). You can reply from the app instead." : "This reply link isn't valid. You can reply from the app instead."}</p>
        <button type="button" onClick={onDismiss} className={dismissCls}>Dismiss</button>
      </>)}
      {info?.outcome === "ok" && !sent && (
        <>
          <p className="mt-2 text-sm text-[var(--dim)]">{info.orgName} · <strong className="text-[var(--text)]">{info.eventTitle}</strong> · {formatDate(info.eventDate)}</p>
          <div className="mt-2 rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2.5 text-sm"><p className="text-xs font-semibold text-[var(--dim)]">{info.aboutSender} wrote:</p><p className="mt-0.5 whitespace-pre-line text-[var(--text)]">{info.aboutBody}</p></div>
          <label htmlFor="msgreply-body" className="mt-3 mb-1 block text-sm font-medium text-[var(--text)]">Your reply</label>
          <textarea id="msgreply-body" value={body} onChange={(e) => setBody(e.target.value)} rows={4} maxLength={2000} placeholder="Write your reply…" className="w-full rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-3 py-2.5 text-[var(--text)]" />
          {error && <p role="alert" className="mt-2 text-sm text-[var(--bad)]">{error}</p>}
          <div className="mt-3 flex gap-2">
            <button type="button" disabled={send.isPending || !body.trim()} onClick={() => send.mutate()} className="rounded-[var(--radius)] bg-[var(--accent)] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{send.isPending ? "Sending…" : "Send reply"}</button>
            <button type="button" onClick={onDismiss} className="rounded-[var(--radius)] border border-[var(--border)] px-4 py-2.5 text-sm font-semibold text-[var(--text)]">Cancel</button>
          </div>
        </>
      )}
      {sent && (<>
        <p className="mt-2 text-sm text-[var(--text)]">✓ Reply sent — it's now part of the message thread for {info?.eventTitle}, and the other side has been notified by email.</p>
        <button type="button" onClick={onDismiss} className={dismissCls}>Done</button>
      </>)}
    </section>
  );
}

function PassCard({ reg }: { reg: Registration }) {
  const branding = useBranding();
  if (!reg.code) return null;
  const primary = branding?.primaryColor ?? "#0b3d6e";
  const sky = branding?.skyColor ?? "#7fb6d9";
  const isVirtual = reg.eventLocationType === "virtual";
  return (<div className="overflow-hidden rounded-[var(--radius)] border-2 bg-[var(--surface)]" style={{ borderColor: primary }}><div className="px-4 py-3 text-white" style={{ backgroundColor: primary }}>{(reg.eventLogoUrl || branding?.logoUrl) && (<img src={reg.eventLogoUrl || branding?.logoUrl} alt="" className="mb-2 max-h-10 w-auto rounded bg-white/95 px-1.5 py-1" />)}<p className="text-xs font-semibold tracking-widest uppercase">{reg.orgName}</p><p className="font-display text-lg leading-snug font-semibold">{reg.eventTitle}</p><p className="text-sm" style={{ color: sky }}>{formatDate(reg.eventDate)} · {reg.eventTimeText}{isVirtual ? " · 💻 Virtual event" : ""}</p></div><div className="flex flex-col items-center gap-3 px-4 py-4">{isVirtual ? (<>
    <p className="text-center text-sm text-[var(--dim)]">{reg.name} — this event meets online. There's no door and no check-in: just join when it's time.</p>
    {reg.eventVirtualLink ? (<a href={reg.eventVirtualLink} target="_blank" rel="noreferrer" className="flex min-h-[56px] w-full items-center justify-center rounded-[var(--radius)] px-4 text-center text-lg font-bold text-white" style={{ backgroundColor: primary }}>🎥 Join the meeting</a>) : (<p className="rounded-[var(--radius)] border border-amber-300 bg-amber-50 px-3 py-2 text-center text-sm text-amber-950">The organizer hasn't added a join link yet — it'll appear here when they do. You can also message the event team below.</p>)}
    <p className="text-center text-xs text-[var(--dim)]">Registration code <span className="font-mono font-bold tracking-widest text-[var(--text)]">{reg.code}</span> — keep it for your records; you won't need it to join.</p>
  </>) : (<>
    <QrPattern code={reg.code} /><p className="text-center text-xs font-semibold tracking-wide text-[var(--dim)] uppercase">Your code</p><p className="font-mono text-xl font-bold tracking-[0.2em] text-[var(--text)]">{reg.code}</p><p className="text-center text-sm text-[var(--dim)]">{reg.name} — show this pass at the door.</p><p className="rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2 text-center text-sm text-[var(--text)]">No camera or printed QR? No problem — <strong>this text code works on its own</strong>: the greeter can type it in to check you in. The QR code is optional.</p>{reg.entryCode && (<div className="w-full rounded-[var(--radius)] border border-teal-300 bg-teal-50 px-3 py-2.5"><p className="text-center text-xs font-semibold tracking-wide text-teal-900 uppercase">Entry code</p><p className="text-center font-mono text-2xl font-bold tracking-[0.3em] text-teal-950">{reg.entryCode}</p><p className="text-center text-xs text-teal-900">This event also takes an entry code — just say or type this code at the door instead of showing your pass.</p></div>)}
  </>)}<p className="text-center text-sm font-semibold text-[var(--text)]">Status: {statusLabel(reg.status)}</p><p className="text-center text-xs text-[var(--dim)]">🔔 Reminders: {reminderSummary(reg)}</p>{reg.sharedCode && reg.groupNames.length > 1 && (<p className="rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2 text-center text-sm text-[var(--text)]">👥 <span className="font-semibold">Shared group pass</span> — this one code covers: {reg.groupNames.join(", ")}.{isVirtual ? " Everyone joins the same meeting." : " Each person is checked in individually at the door."}</p>)}<CalendarInviteButton reg={reg} />{!isVirtual && <WalletButtons reg={reg} />}</div></div>);
}
