  const changeNotifyM = useMutation({ mutationFn: (cp: { eventId: number; title: string; changes: string[] }) => api.sendAttendeeMessage({ eventId: cp.eventId, audience: "all", template: "time_change", subject: `Changed: ${cp.title}`, body: `We changed ${cp.title}: ${cp.changes.join("; ")}. Your pass and My Events already show the new details — please use those.`, ...requesterArgs, senderName: googleUser.name }), onSuccess: () => { setChangePrompt(null); setChangeWarned(false); }, onError: (e) => setActionError(e instanceof Error ? e.message : "Couldn't send the change notice.") });
