  const allEvents = allEventsQ.data?.events ?? events;
  const regCounts = new Map<number, { total: number; checkedIn: number }>();
  for (const r of regs.data?.registrations ?? []) { const c = regCounts.get(r.eventId) ?? { total: 0, checkedIn: 0 }; if (r.status !== "revoked") c.total += 1; if (r.status === "checked_in") c.checkedIn += 1; regCounts.set(r.eventId, c); }
  const samplePerson = (regs.data?.registrations ?? []).find((r) => r.status !== "revoked" && r.status !== "denied")?.name;
  const sampleEventTitle = (() => { let best: string | undefined; let bestCount = 0; for (const [evId, c] of regCounts) { if (c.total > bestCount) { bestCount = c.total; best = allEvents.find((e) => e.id === evId)?.title; } } return best ?? allEvents[0]?.title; })();
  const assistantRef = useRef<HTMLDivElement | null>(null);
