/* ---------- Device location (greeter check-in is location-bound) ---------- */
type DeviceLoc = { status: "idle" | "locating" | "ok" | "denied" | "unsupported"; lat: number | null; lng: number | null; accuracy: number | null };
function useDeviceLocation() {
  const [loc, setLoc] = useState<DeviceLoc>({ status: "idle", lat: null, lng: null, accuracy: null });
  const refresh = () => {
    if (typeof navigator === "undefined" || !navigator.geolocation) { setLoc({ status: "unsupported", lat: null, lng: null, accuracy: null }); return; }
    setLoc((p) => ({ ...p, status: "locating" }));
    navigator.geolocation.getCurrentPosition(
      (pos) => setLoc({ status: "ok", lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: Math.round(pos.coords.accuracy) }),
      () => setLoc({ status: "denied", lat: null, lng: null, accuracy: null }),
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 30000 },
    );
  };
  useEffect(() => { refresh(); }, []);
  return { loc, refresh };
}
function haversineMetersClient(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const R = 6371000; const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1); const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(a)));
}
function LocationStatusBar({ loc, refresh }: { loc: DeviceLoc; refresh: () => void }) {
  return (
    <div role="status" className={`rounded-[var(--radius)] border px-4 py-3 ${loc.status === "ok" ? "border-sky-300 bg-sky-50" : "border-amber-400 bg-amber-50"}`}>
      <p className="text-sm font-bold text-[var(--text)]">📍 {loc.status === "ok" ? <>Device location found{loc.accuracy ? <> (±{loc.accuracy} m)</> : ""} — you're set for location-checked check-in.</> : loc.status === "locating" ? "Finding this device's location…" : loc.status === "unsupported" ? "This browser can't share its location." : "Location isn't available on this device yet."}</p>
      <p className="mt-0.5 text-sm text-[var(--dim)]">{loc.status === "ok" ? "In-person check-in is location-bound: it works when this phone is within the event's radius of the venue. Virtual events have no check-in at all." : "Check-in for in-person events is location-bound — this phone must be at the venue. Allow location access for this site, then re-check."}</p>
      <button type="button" onClick={refresh} className="mt-2 min-h-[40px] rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-3.5 py-2 text-sm font-semibold text-[var(--text)]">Re-check my location</button>
    </div>
  );
}

/* ---------- Subscribe to an organization (attendee new-event alerts) ----------
   No account or membership needed — just an email address. Signed-in
   attendees subscribe in one tap with their sign-in email; everyone
   else types an address (remembered on this device for the next
   organization). The server stores it encrypted and notifies
   subscribers automatically when the organization posts a new event. */
function OrgSubscribeControl({ org, googleUser, compact = false }: { org: Org; googleUser: GoogleUser | null; compact?: boolean }) {
  const queryClient = useQueryClient();
  const [email, setEmail] = useState<string>(() => googleUser?.email ?? lsRead<string>("ag-sub-email", ""));
  const [note, setNote] = useState<string | null>(null);
  useEffect(() => { if (googleUser?.email) setEmail(googleUser.email); }, [googleUser?.email]);
  const effectiveEmail = email.trim().toLowerCase();
  const emailKnown = effectiveEmail.includes("@");
  const stateQ = useQuery({ queryKey: ["subState", org.id, effectiveEmail], queryFn: () => api.getSubscriptionState({ orgId: org.id, email: emailKnown ? effectiveEmail : undefined }), enabled: emailKnown });
  const subscribed = stateQ.data?.subscribed === true;
  const sub = useMutation({
    mutationFn: () => api.subscribeToOrganization({ orgId: org.id, email: effectiveEmail, name: googleUser?.name ?? "" }),
    onSuccess: (d) => { lsWrite("ag-sub-email", effectiveEmail); setNote(d.alreadySubscribed ? `You're already subscribed to ${org.name}.` : `✓ Subscribed — new ${org.name} events will be announced to ${effectiveEmail}.`); queryClient.invalidateQueries({ queryKey: ["subState", org.id] }); },
    onError: (e) => setNote(e instanceof Error ? e.message : "Couldn't subscribe just now — try again."),
  });
  const unsub = useMutation({
    mutationFn: () => api.unsubscribeFromOrganization({ orgId: org.id, email: effectiveEmail }),
    onSuccess: () => { setNote(`Unsubscribed — no more new-event alerts from ${org.name}.`); queryClient.invalidateQueries({ queryKey: ["subState", org.id] }); },
    onError: (e) => setNote(e instanceof Error ? e.message : "Couldn't unsubscribe just now — try again."),
  });
  if (subscribed) {
    return (
      <div className={compact ? "mt-1.5" : "mt-3 rounded-[var(--radius)] border border-emerald-300 bg-emerald-50 px-3.5 py-3"}>
        <p className="text-sm font-semibold text-emerald-950">✓ Subscribed to {org.name} — new-event alerts go to {effectiveEmail}.</p>
        <div className="mt-1.5 flex flex-wrap items-center gap-2">
          <button type="button" disabled={unsub.isPending} onClick={() => { setNote(null); unsub.mutate(); }} className="min-h-[36px] rounded-full border border-emerald-700 px-3 py-1.5 text-sm font-semibold text-emerald-900 disabled:opacity-50">Unsubscribe</button>
          {stateQ.data && stateQ.data.subscriberCount > 1 && <span className="text-xs text-emerald-900">{stateQ.data.subscriberCount} people subscribed</span>}
        </div>
        {note && <p role="status" className="mt-1.5 text-sm text-emerald-950">{note}</p>}
      </div>
    );
  }
  return (
    <div className={compact ? "mt-1.5" : "mt-3 rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] px-3.5 py-3"}>
      <p className="text-sm font-semibold text-[var(--text)]">🔔 Get new-event alerts from {org.name}</p>
      {!compact && <ul className="mt-1 space-y-0.5 text-sm font-semibold text-[var(--dim)]"><li>✓ New {org.name} events, straight to your inbox</li><li>✓ No account needed</li><li>✓ Unsubscribe any time</li></ul>}
      <form onSubmit={(e) => { e.preventDefault(); setNote(null); if (emailKnown) sub.mutate(); }} className="mt-2 flex flex-wrap gap-2">
        {!googleUser && (<><label htmlFor={`sub-email-${org.id}${compact ? "-c" : ""}`} className="sr-only">Email for new-event alerts from {org.name}</label><input id={`sub-email-${org.id}${compact ? "-c" : ""}`} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.org" autoComplete="email" className="min-h-[44px] min-w-[180px] flex-1 rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2 text-[var(--text)]" /></>)}
        <button type="submit" disabled={!emailKnown || sub.isPending} className="min-h-[44px] rounded-[var(--radius)] px-4 py-2 text-sm font-bold text-white disabled:opacity-50" style={{ backgroundColor: org.primaryColor }}>{sub.isPending ? "Subscribing…" : googleUser ? `Subscribe with ${googleUser.email}` : "Subscribe"}</button>
      </form>
      {note && <p role="status" className="mt-1.5 text-sm text-[var(--text)]">{note}</p>}
    </div>
  );
}

